const NeuroAI = (() => {
    const e = hubUtils.escapeHtml, u = hubUtils.sourceHref, d = neuroAIData;
    const categories = {
        mapping: { title: 'Map & measure', question: 'How can AI reveal the brain’s structure and activity?', icon: '01' },
        models: { title: 'Model & emulate', question: 'What can a model predict about a brain or its behavior?', icon: '02' },
        learning: { title: 'Learn from brains', question: 'What can biological intelligence teach us about AI?', icon: '03' },
        living: { title: 'Compute with cells', question: 'What happens when living neurons enter a feedback loop?', icon: '04' }
    };
    const byId = (id) => d.projects.find(p => p.id === id);
    const href = (id = '', params = {}) => { const q = new URLSearchParams(params); return '#neuroai' + (id ? '/' + encodeURIComponent(id) : '') + (q.size ? '?' + q.toString() : ''); };
    const link = (s, label = s.title) => `<a href="${u(s.url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`;
    const nodes = [[63, 81], [124, 43], [129, 129], [209, 62], [219, 137], [281, 89]];
    function art(kind = 'models') {
        let svg = '';
        if (kind === 'mapping')
            svg = `${Array.from({ length: 5 }, (_, i) => `<rect x="${47 + i * 11}" y="${29 + i * 9}" width="105" height="100" rx="6" fill="none" stroke="currentColor" opacity="${.2 + i * .15}"/>`).join('')}<path d="M182 99h35m-9-7 9 7-9 7"/><path d="M257 144V82l-25-30m25 50 33-35m-33 63 32-6m-48 27 16-26"/>${[[257, 82], [232, 52], [290, 67], [289, 124], [241, 151]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="6"/>`).join('')}`;
        else if (kind === 'learning')
            svg = `<path d="M46 37v128h254" opacity=".25"/><path d="m49 140 27-12 26-59 27 39 27-20 27 34 28-58 27-16 28 46 29-17" stroke-width="3"/><path d="m49 143 27-19 26-39 27 26 27-13 27 19 28-41 27-20 28 44 29-17" stroke-width="3" stroke-dasharray="5 6" opacity=".45"/><path d="M61 190h27" stroke-width="3"/><text x="96" y="195">observed</text><path d="M194 190h27" stroke-width="3" stroke-dasharray="4 5" opacity=".45"/><text x="229" y="195">predicted</text><text x="64" y="29">held-out observations</text>`;
        else if (kind === 'living')
            svg = `<ellipse cx="173" cy="95" rx="117" ry="65" fill="none"/><ellipse cx="173" cy="102" rx="96" ry="44" fill="currentColor" opacity=".08"/>${nodes.slice(1, 5).map(([x, y]) => `<circle cx="${x}" cy="${y}" r="10"/><path d="M${x - 24} ${y - 16}l24 16 21-15m-21 15 8 24"/>`).join('')}<path d="M50 88H23v96h300V89h-29" stroke-dasharray="4 5"/><path d="m294 83-8 6 8 6"/>`;
        else if (kind === 'trading')
            svg = `<rect x="22" y="55" width="77" height="80" rx="8" fill="none"/><path d="m32 111 13-18 11 9 13-25 15 7"/>${nodes.slice(1, 5).map(([x, y]) => `<circle cx="${115 + (x - 124) * .8}" cy="${55 + (y - 43) * .6}" r="7"/>`).join('')}<path d="M99 94h19m-7-6 7 6-7 6m16-36 68 50m-64 0 66-45m5 25h25m-7-6 7 6-7 6"/><rect x="249" y="56" width="70" height="78" rx="8" fill="none"/><text x="284" y="84" text-anchor="middle">BUY</text><text x="284" y="103" text-anchor="middle">SELL</text><text x="284" y="122" text-anchor="middle">HOLD</text><path d="M283 142v28H165v-31" stroke-dasharray="4 5"/><text x="188" y="195" text-anchor="middle">simulated reward feedback</text>`;
        else
            svg = `${[[0, 1], [0, 2], [1, 3], [1, 2], [2, 4], [3, 4], [3, 5], [4, 5]].map(([a, b]) => `<path d="M${nodes[a][0]} ${nodes[a][1]}L${nodes[b][0]} ${nodes[b][1]}" opacity=".55"/>`).join('')}${nodes.map(([x, y], i) => `<circle cx="${x}" cy="${y}" r="${i === 3 ? 15 : 10}" opacity="${.4 + i * .1}"/>`).join('')}<path d="M37 177h25l8-18 8 30 8-20 8 8h22l8-11 8 20 8-9h35l8-18 8 30 8-20 8 8h45" fill="none"/>`;
        return `<svg class="ai-schematic" viewBox="0 0 340 220" role="img" aria-label="Illustrative ${e(kind === 'trading' ? 'market input, simulated circuit, action and reward loop' : kind === 'learning' ? 'observed and predicted example traces' : categories[kind]?.title || 'neural model')} diagram"><g fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${svg}</g></svg>`;
    }
    function picture(image, hero = false) { return `<figure class="ai-photo${hero ? ' ai-hero-photo' : ''}"><div class="ai-photo-frame"><img src="${u(image.url)}" alt="${e(image.alt)}" loading="${hero ? 'eager' : 'lazy'}" decoding="async" data-ai-image><a class="ai-open-image" href="${u(image.url)}" target="_blank" rel="noopener noreferrer" aria-label="View image: ${e(image.alt)}">View image ↗</a><span class="ai-photo-error" hidden>Image unavailable. The credited source below remains available.</span></div><figcaption><span>${e(image.caption)}</span>${link({ title: image.credit, url: image.source })}</figcaption></figure>`; }
    function cover(p) { return p.image ? picture(p.image) : `<figure class="ai-concept" data-category="${e(p.category)}">${art(p.diagram || p.category)}<figcaption>Explanatory schematic · not an experimental result</figcaption></figure>`; }
    function nav(view) { return `<nav class="ai-tabs" aria-label="NeuroAI views">${[['projects', 'Explore projects'], ['explain', 'How it works'], ['learn', 'Start learning']].map(([id, label]) => `<a data-ai-nav href="${href('', id === 'projects' ? {} : { view: id })}"${view === id ? ' aria-current="page"' : ''}>${label}</a>`).join('')}</nav>`; }
    function head(compact = false) { return `<header class="ai-head${compact ? ' ai-head-small' : ''}"><div><span class="eyebrow">NEUROAI · BRAINS, MODELS &amp; MACHINES</span><h1>How do we learn<br> <em>from a brain?</em></h1><p>AI helps us map and model nervous systems. Biological intelligence gives us new questions, tests, and designs for AI.</p><div class="ai-head-links"><a data-ai-nav href="${href('', { view: 'explain' })}">Understand the big picture →</a><span>${d.projects.length} selected projects · reviewed ${e(d.reviewed)}</span></div></div>${compact ? '' : picture(d.hero, true)}</header>`; }
    function sectionHead(kicker, title, description) { return `<header class="ai-section-head"><span class="eyebrow">${e(kicker)}</span><h1>${e(title)}</h1><p>${e(description)}</p></header>`; }
    function card(p) { return `<article class="ai-project-card" data-category="${e(p.category)}">${cover(p)}<div class="ai-card-body"><div class="ai-meta"><span>${e(p.evidence)}</span><span>${e(p.date)}</span></div><h3><a data-ai-nav href="${href(p.id)}">${e(p.title)} ↗</a></h3><p>${e(p.summary)}</p><div class="ai-card-footer"><span>${e(categories[p.category].title)}</span><a data-ai-nav href="${href(p.id)}">See how it works →</a></div></div></article>`; }
    function state(params) { const q = params.get('q') || '', category = params.get('category') || ''; return { q, category, projects: d.projects.filter(p => (!category || p.category === category) && hubUtils.matches([p.title, p.subtitle, p.summary, p.does, p.evidence].join(' '), q)) }; }
    function projects(params) { const s = state(params); return `${head()}${nav('projects')}<section class="ai-entry"><div><span class="eyebrow">A FIELD WITH FOUR CONNECTED DIRECTIONS</span><h2>Start with the question.</h2></div><p>Some projects map real tissue. Others predict activity, control a virtual body, or put living cells in a loop. The project pages show which kind of evidence is available.</p></section><div class="ai-directions">${Object.entries(categories).map(([id, c]) => `<a data-ai-nav href="${href('', { category: id })}"${s.category === id ? ' aria-current="true"' : ''}><b>${c.icon}</b><strong>${e(c.title)}</strong><span>${e(c.question)}</span></a>`).join('')}</div><form id="ai-filter" class="ai-filter" role="search"><label>Find a project<input id="ai-query" type="search" value="${e(s.q)}" placeholder="Try fly, brain model, learning, or neurons"></label><label>Direction<select id="ai-category"><option value="">All directions</option>${Object.entries(categories).map(([id, c]) => `<option value="${id}"${s.category === id ? ' selected' : ''}>${e(c.title)}</option>`).join('')}</select></label><button type="submit">Find projects</button></form><div class="ai-result-count" role="status">${s.projects.length} of ${d.projects.length} projects${s.category ? ' · ' + e(categories[s.category]?.title || 'Unknown direction') : ''}${s.q || s.category ? `<a data-ai-nav href="#neuroai">Clear filters</a>` : ''}</div><div class="ai-project-grid">${s.projects.map(card).join('') || '<div class="ai-empty"><h2>No matching projects.</h2><a data-ai-nav href="#neuroai">Explore all projects →</a></div>'}</div><aside class="ai-notebook-bridge"><div><span class="eyebrow">TURN CURIOSITY INTO A QUESTION</span><h2>Could a fly circuit learn a new objective?</h2><p>The Bitcoin demo becomes an experimental question: what changed inside the model, and did feedback improve behavior on unseen data?</p></div><a href="#ideas/fly-circuit-learning">Open the research note →</a></aside>`; }
    const stages = [
        { id: 'map', title: 'Map', subtitle: 'What is connected?', input: 'Microscope images', output: 'Neurons, synapses, cell types', text: 'A connectome describes anatomical connections reconstructed from tissue. AI can trace cells, while proofreading and annotation help establish what those reconstructions mean.', missing: 'Wiring alone does not specify all synaptic strengths, dynamics, plasticity, or the animal’s changing internal state.', question: 'Which specimen, regions, connections, and errors does this release include?', projects: ['male-cns', 'flywire', 'microns'], kind: 'mapping' },
        { id: 'model', title: 'Model', subtitle: 'What rules make it run?', input: 'Anatomy or recordings + assumptions', output: 'Simulated activity or learned representations', text: 'Researchers add equations, parameters and inputs to a structural map, or learn a statistical model from recordings. These choices determine the model’s behavior.', missing: 'A neuron count is not a measure of predictive accuracy. Different models can use the same map and produce different outputs.', question: 'What was measured, what was fitted, and what was assumed?', projects: ['shiu-fly', 'eon', 'cebra'], kind: 'models' },
        { id: 'act', title: 'Act', subtitle: 'How does it meet the world?', input: 'Sensory encoding + controller', output: 'A virtual body or task action', text: 'A simulated circuit needs inputs and an output interface. A virtual fly body or a buy/sell readout adds another engineering layer; its training and mappings affect the result.', missing: 'Successful control does not by itself establish a faithful copy of an individual brain. A programmed task interface is part of the system.', question: 'Which decisions come from neural dynamics, and which come from the controller?', projects: ['eon', 'stonkfly', 'flygym'], kind: 'trading' },
        { id: 'test', title: 'Test', subtitle: 'What survives a fair comparison?', input: 'Held-out data + interventions', output: 'An evaluated prediction', text: 'Compare the model with observations it was not fitted to. Use appropriate baselines, perturb the proposed mechanism and report uncertainty as well as successful examples.', missing: 'A demonstration, an attractive animation and an open repository answer different questions from a controlled benchmark.', question: 'Does the proposed mechanism improve results beyond a simpler explanation?', projects: ['brainscore', 'zapbench', 'stonkfly'], kind: 'learning' }
    ];
    function stageIndex(params) { const n = Number(params.get('stage')); return Number.isInteger(n) && n >= 0 && n < stages.length ? n : 0; }
    function explain(params) { const index = stageIndex(params), s = stages[index]; return `${nav('explain')}${sectionHead('ONE IDEA, FOUR LAYERS', 'From a brain map to a testable model.', 'Follow the layers below. Each step adds useful capabilities—and assumptions that need testing.')}<div class="ai-stage-nav" role="group" aria-label="Choose an explanation layer">${stages.map((s, i) => `<button type="button" data-ai-stage="${i}" aria-pressed="${i === index}"><span>${i + 1}</span><strong>${s.title}</strong><small>${e(s.subtitle)}</small></button>`).join('')}</div><section id="ai-stage" class="ai-stage" aria-live="polite" aria-atomic="true"><div class="ai-stage-art" data-category="${s.kind}">${art(s.kind)}<div><span>${e(s.input)}</span><b aria-hidden="true">→</b><strong>${e(s.output)}</strong></div><small>Conceptual diagram · not a simulation</small></div><div class="ai-stage-copy"><span class="eyebrow">LAYER ${index + 1} / 4</span><h2>${s.title}: ${e(s.subtitle)}</h2><p>${e(s.text)}</p><div class="ai-boundary"><strong>What this layer leaves open</strong><p>${e(s.missing)}</p></div><h3>The question to ask</h3><p>${e(s.question)}</p><div class="ai-stage-projects">${s.projects.map(byId).filter(Boolean).map(p => `<a data-ai-nav href="${href(p.id)}">${e(p.title)} ↗</a>`).join('')}</div></div></section><div class="ai-stage-controls"><button data-ai-stage="${Math.max(0, index - 1)}"${index === 0 ? ' disabled' : ''}>← Previous layer</button><span>${index + 1} / 4</span><button data-ai-stage="${Math.min(3, index + 1)}"${index === 3 ? ' disabled' : ''}>Next layer →</button></div><aside class="ai-count-note"><h2>Counts describe different things.</h2><p>An anatomical neuron count, a synapse count, a weighted graph edge and a recording channel are different units. A model can combine several anatomical synapses into one connection weight.</p><a href="#ideas/connectome-to-model">Explore the counting question ↗</a><a href="#visuals?group=explainers">Understand recording sites and channels ↗</a></aside>`; }
    function detail(p) { const video = p.video ? NeuroMedia.video({ media: { video: p.video } }) : ''; return `${nav('projects')}<a class="ai-back" data-ai-nav href="#neuroai">← Explore all NeuroAI projects</a><header class="ai-detail-head"><span class="eyebrow">${e(categories[p.category].title)} · ${e(p.evidence)}</span><h1>${e(p.title)}</h1><p>${e(p.subtitle)}</p><small>Source date: ${e(p.date)} · reviewed ${e(d.reviewed)}</small></header><div class="ai-detail-intro">${cover(p)}<div><span class="eyebrow">WHY IT IS INTERESTING</span><h2>${e(p.question)}</h2><p>${e(p.summary)}</p><div class="ai-actions">${p.actions.map(a => `<div>${link({ title: a.label, url: a.url })}${a.note ? `<small>${e(a.note)}</small>` : ''}</div>`).join('')}</div></div></div>${p.facts.length ? `<dl class="ai-facts">${p.facts.map(f => `<div><dd>${e(f.value)}</dd><dt>${e(f.label)}</dt>${f.note ? `<small>${e(f.note)}</small>` : ''}</div>`).join('')}</dl>` : ''}<div class="ai-evidence-panels"><section><span class="eyebrow">WHAT THE SOURCES SHOW</span><h2>What it does</h2><p>${e(p.does)}</p></section><section><span class="eyebrow">HOW TO INTERPRET IT</span><h2>What remains open</h2><p>${e(p.boundary)}</p></section><section><span class="eyebrow">AN IDEA TO INVESTIGATE</span><h2>A useful next test</h2><p>${e(p.nextTest)}</p><small>Editorial research question, not a reported result.</small></section></div>${video}${p.people?.length ? `<section class="ai-people-links"><h2>People behind the work</h2>${p.people.map(s => `<a href="${s.href.startsWith('#') ? e(s.href) : u(s.href)}">${e(s.label)} ↗</a>`).join('')}</section>` : ''}<section class="ai-source-trail"><div><span class="eyebrow">GO BACK TO THE ORIGINAL WORK</span><h2>Follow the source trail.</h2><p>Research papers, tools, project documentation and company demonstrations keep their own labels and dates.</p></div><ol>${p.sources.map(s => `<li>${link(s)}${s.detail ? `<p>${e(s.detail)}</p>` : ''}</li>`).join('')}</ol></section><section class="ai-related"><h2>Keep exploring</h2><div>${p.related.map(byId).filter(Boolean).map(p => `<a data-ai-nav href="${href(p.id)}"><span>${e(categories[p.category].title)}</span><strong>${e(p.title)} →</strong><small>${e(p.evidence)}</small></a>`).join('')}</div><a data-ai-nav href="${href('', { view: 'explain' })}">Follow map → model → action → test ↗</a></section>`; }
    function learn() { const paths = [{ title: 'Understand the field', time: 'Read & explore', href: '#topic/neuroai', text: 'Learn the vocabulary and distinguish a brain map, a predictive model, an emulation and a living neural system.' }, { title: 'Follow a connectome', time: 'No-code starting point', href: '#learn/connectome', text: 'Inspect a real fly dataset, choose a neuron and follow documented connections before thinking about a simulation.' }, { title: 'Test a neural representation', time: 'A Python learning project', href: '#learn/neuroai', text: 'Choose a prediction task, build a baseline and ask whether the model generalizes to held-out data.' }]; return `${nav('learn')}${sectionHead('NEUROAI · A PRACTICAL START', 'Find your first experiment.', 'Follow a real circuit, understand a model, or test a prediction. These paths connect the concepts to tools you can inspect.')}<div class="ai-learning-paths">${paths.map((p, i) => `<article><span>0${i + 1} / ${p.time}</span><h2>${p.title}</h2><p>${p.text}</p><a href="${p.href}">Open this path →</a></article>`).join('')}</div><div class="ai-section-heading"><h2>A practical toolkit</h2><a href="#resources?topic=neuroai">Open the full resource library ↗</a></div><div class="ai-tool-grid">${d.resources.map(r => `<article><span>${e(r.type)} · ${e(r.level)}</span><h3>${link(r)}</h3><p>${e(r.description)}</p><small>Link reviewed ${e(r.reviewed || d.reviewed)}</small></article>`).join('')}</div>`; }
    function render(id = '', params = new URLSearchParams()) { const view = params.get('view') || 'projects'; return `<div class="ai-page" data-ai-view="${id ? 'project' : e(view)}">${id ? (byId(id) ? detail(byId(id)) : '<h1>Project not found.</h1><a href="#neuroai">Explore NeuroAI →</a>') : view === 'explain' ? explain(params) : view === 'learn' ? learn() : projects(params)}</div>`; }
    function bind(container, params, navigate) {
        container.querySelectorAll('[data-ai-nav]').forEach(a => a.addEventListener('click', ev => { if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey)
            return; ev.preventDefault(); navigate(a.getAttribute('href')); }));
        container.querySelector('#ai-filter')?.addEventListener('submit', ev => { ev.preventDefault(); const q = container.querySelector('#ai-query').value.trim(), category = container.querySelector('#ai-category').value; navigate(href('', { ...(q ? { q } : {}), ...(category ? { category } : {}) }), 'ai-query'); });
        container.querySelectorAll('[data-ai-stage]').forEach((button, i) => { button.id = 'ai-stage-control-' + i; button.addEventListener('click', () => { const q = new URLSearchParams(params); q.set('view', 'explain'); q.set('stage', button.dataset.aiStage); navigate(href('', q), 'ai-stage-control-' + Math.min(3, Number(button.dataset.aiStage))); }); });
        bindImages(container);
        NeuroMedia.bind(container);
    }
    function bindImages(container) {
        container.querySelectorAll('[data-ai-image]').forEach(img => { if (img.dataset.aiImageBound)
            return; img.dataset.aiImageBound = 'true'; const fail = () => { img.hidden = true; const text = img.parentElement?.querySelector('.ai-photo-error'); if (text)
            text.hidden = false; }; img.addEventListener('error', fail, { once: true }); if (img.complete && !img.naturalWidth)
            fail(); });
    }
    function records() { return [{ id: 'neuroai', title: 'NeuroAI, brain models & emulation', description: 'Maps, models, embodied agents and living neural computing, with tools and learning paths.', kind: 'NeuroAI', href: '#neuroai' }, ...d.projects.map(p => ({ id: 'neuroai-' + p.id, title: p.title, description: p.summary, kind: 'NeuroAI project', href: href(p.id), keywords: p.subtitle + ' ' + p.category + ' ' + p.evidence }))]; }
    function spotlight() { return `<a class="ai-spotlight" href="#neuroai"><div><span class="eyebrow">A NEW WAY INTO THE BRAIN</span><h2>Brain maps. Digital flies.<br>NeuroAI.</h2><p>Explore what these projects can teach us—and try the tools behind them.</p><strong>Follow the ideas →</strong></div><img src="${u(d.hero.url)}" alt="${e(d.hero.alt)}" loading="lazy"><small>Image: ${e(d.hero.credit)} · source and caption inside</small></a>`; }
    function idea(id) { if (!['fly-circuit-learning', 'connectome-to-model'].includes(id))
        return ''; return `<aside class="ai-page ai-idea-visual">${id === 'connectome-to-model' ? picture(d.hero) : `<figure class="ai-concept">${art('trading')}<figcaption>Conceptual task loop · computational model</figcaption></figure>`}<h3>${id === 'connectome-to-model' ? 'Anatomy is one layer of a model.' : 'Where does learning happen?'}</h3><p>Trace the dataset, assumptions, task interface and evidence before interpreting the result.</p><a href="${href(id === 'connectome-to-model' ? 'male-cns' : 'stonkfly')}">Open the source-linked project →</a><a href="#neuroai?view=explain">Follow the four-layer explanation →</a></aside>`; }
    return { render, bind, bindImages, records, spotlight, art, state, stageIndex, categories, idea };
})();
